3.org.hibernate.loader.Loaderprivate List listIgnoreQueryCache(SharedSessionContractImplementor session, QueryParameters queryParameters) &#123;
        return this.getResultList(this.doList(session, queryParameters), queryParameters.getResultTransformer());
